// ===== Embedded launchers + Downgrade (built-in) =====
var SIRMAN_LAUNCHER_TEMPLATES_B64 = {
  "Sirman_Start.bat": "",
  "OPEN_SIRMAN.bat": "",
  "sirman_run.ps1": "",
  "\u0627\u062c\u0631\u0627\u06cc \u0633\u06cc\u0631\u0645\u0627\u0646.bat": "QGVjaG8gb2ZmCmNkIC9kICIlfmRwMCIKY2FsbCAiJX5kcDBTaXJtYW5fU3RhcnQuYmF0Igo="
};

var SIRMAN_LAUNCHER_TEMPLATES = null;
function sirmanB64ToUtf8(b64){
  b64 = String(b64 || '').replace(/\s+/g, '');
  var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  var output = [];
  var buffer = 0, bits = 0;
  for (var i = 0; i < b64.length; i++) {
    var c = b64.charAt(i);
    if (c === '=') break;
    var val = chars.indexOf(c);
    if (val < 0) continue;
    buffer = (buffer << 6) | val;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      output.push((buffer >> bits) & 0xFF);
    }
  }
  // UTF-8 decode
  var out = '', j = 0;
  while (j < output.length) {
    var b0 = output[j++];
    if (b0 < 128) out += String.fromCharCode(b0);
    else if (b0 >= 192 && b0 < 224) {
      var b1 = output[j++] || 0;
      out += String.fromCharCode(((b0 & 31) << 6) | (b1 & 63));
    } else if (b0 >= 224 && b0 < 240) {
      var b1b = output[j++] || 0, b2 = output[j++] || 0;
      out += String.fromCharCode(((b0 & 15) << 12) | ((b1b & 63) << 6) | (b2 & 63));
    } else {
      var b1c = output[j++] || 0, b2b = output[j++] || 0, b3 = output[j++] || 0;
      var cp = ((b0 & 7) << 18) | ((b1c & 63) << 12) | ((b2b & 63) << 6) | (b3 & 63);
      cp -= 0x10000;
      out += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
    }
  }
  return out;
}
function ensureLauncherTemplates(){
  if (SIRMAN_LAUNCHER_TEMPLATES) return SIRMAN_LAUNCHER_TEMPLATES;
  SIRMAN_LAUNCHER_TEMPLATES = {};
  Object.keys(SIRMAN_LAUNCHER_TEMPLATES_B64 || {}).forEach(function(k){
    SIRMAN_LAUNCHER_TEMPLATES[k] = sirmanB64ToUtf8(SIRMAN_LAUNCHER_TEMPLATES_B64[k]);
  });
  return SIRMAN_LAUNCHER_TEMPLATES;
}

function getLauncherVersionTag(){
  try { return (typeof APP_VERSION !== 'undefined' && APP_VERSION) ? String(APP_VERSION) : '1405.5.18ζ'; }
  catch(_e){ return '1405.5.18ζ'; }
}
function buildEmbeddedLauncher(name){
  var map = ensureLauncherTemplates();
  var tpl = map[name];
  if(!tpl) throw new Error('لانچر ناشناخته: '+name);
  return String(tpl).split('__SIRMAN_VERSION__').join(getLauncherVersionTag());
}
function downloadTextFile(filename, text, mime){
  var blob = new Blob([text], { type: mime || 'text/plain;charset=utf-8' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(function(){ try{ URL.revokeObjectURL(a.href); a.remove(); }catch(_e){} }, 1500);
}
function downloadEmbeddedLauncher(name){
  try{
    var body = buildEmbeddedLauncher(name);
    downloadTextFile(name, body, /\.ps1$/i.test(name) ? 'text/plain;charset=utf-8' : 'application/octet-stream');
    if(typeof ntf==='function') ntf('دانلود شد: '+name+' (نسخه '+getLauncherVersionTag()+')');
  }catch(e){
    if(typeof ntf==='function') ntf('دانلود لانچر ناموفق','err');
    alert(e.message||String(e));
  }
}
function downloadAllEmbeddedLaunchers(){
  var names = Object.keys(ensureLauncherTemplates());
  for(var i=0;i<names.length;i++){
    (function(n, delay){ setTimeout(function(){ downloadEmbeddedLauncher(n); }, delay); })(names[i], i*400);
  }
}
function getVersionSnapshots(){
  try{
    var raw = localStorage.getItem('laegh_version_snapshots');
    var arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  }catch(_e){ return []; }
}
function saveVersionSnapshots(arr){
  localStorage.setItem('laegh_version_snapshots', JSON.stringify((arr||[]).slice(-40)));
}
function pushVersionSnapshot(reason){
  var snaps = getVersionSnapshots();
  var meta = (typeof getAppliedUpdatesMeta==='function') ? getAppliedUpdatesMeta() : [];
  snaps.push({
    at: new Date().toISOString(),
    reason: reason || 'manual',
    version: (typeof APP_VERSION!=='undefined'?APP_VERSION:''),
    versionFa: (typeof APP_VERSION_FA!=='undefined'?APP_VERSION_FA:''),
    baseVersion: (typeof APP_BASE_VERSION!=='undefined'?APP_BASE_VERSION:''),
    updateIds: meta.map(function(m){ return m.id; }),
    updates: meta
  });
  saveVersionSnapshots(snaps);
}
function listDowngradeTargets(){
  var out = [];
  out.push({ key: 'base', label: 'هسته HTML ('+((typeof APP_BASE_VERSION!=='undefined')?APP_BASE_VERSION:'?')+')', kind:'base' });
  var meta = (typeof getAppliedUpdatesMeta==='function') ? getAppliedUpdatesMeta() : [];
  for(var i=0;i<meta.length;i++){
    var m = meta[i];
    out.push({ key: 'upd:'+m.id, label: (m.versionFa||m.version||m.id)+' — '+(m.title||m.id), kind:'update', id:m.id, index:i, version:m.version });
  }
  var snaps = getVersionSnapshots().slice().reverse();
  var seen = {};
  out.forEach(function(t){ seen[t.label]=1; });
  snaps.forEach(function(s, idx){
    var lab = 'اسنپ‌شات: '+(s.versionFa||s.version||'?')+' @ '+String(s.at||'').replace('T',' ').slice(0,19);
    if(seen[lab]) return;
    seen[lab]=1;
    out.push({ key: 'snap:'+idx, label: lab, kind:'snapshot', snap: s });
  });
  return out;
}
async function downgradeToTarget(targetKey){
  if(!targetKey){ alert('یک نسخه برای بازگشت انتخاب کنید'); return; }
  var targets = listDowngradeTargets();
  var t = null;
  for(var i=0;i<targets.length;i++){ if(targets[i].key===targetKey){ t=targets[i]; break; } }
  if(!t){ alert('هدف دانگرید پیدا نشد'); return; }
  if(!confirm('بازگشت (دانگرید) به:\n'+t.label+'\n\nآپدیت‌های بعد از این نقطه حذف می‌شوند. داده کسب‌وکار پاک نمی‌شود.')) return;
  var word = prompt('برای تأیید دانگرید، کلمه «تایید» را تایپ کنید:');
  if(word !== 'تایید'){ if(typeof ntf==='function') ntf('لغو شد'); return; }
  pushVersionSnapshot('before-downgrade');
  if(t.kind === 'base'){
    var meta = getAppliedUpdatesMeta();
    await Promise.all(meta.map(function(m){ return deleteStoredUpdatePackage(m.id); }));
    saveAppliedUpdatesMeta([]);
    setRuntimeAppVersion(APP_BASE_VERSION, toPersianVersionDigits(APP_BASE_VERSION));
    if(typeof ntf==='function') ntf('دانگرید به هسته انجام شد');
    setTimeout(function(){ location.reload(); }, 500);
    return;
  }
  if(t.kind === 'update'){
    var meta2 = getAppliedUpdatesMeta();
    var keep = [], remove = [], found = false;
    for(var j=0;j<meta2.length;j++){
      if(!found){ keep.push(meta2[j]); if(meta2[j].id === t.id) found = true; }
      else remove.push(meta2[j]);
    }
    if(!found){ alert('آپدیت هدف در تاریخچه نیست'); return; }
    await Promise.all(remove.map(function(m){ return deleteStoredUpdatePackage(m.id); }));
    saveAppliedUpdatesMeta(keep);
    if(typeof ntf==='function') ntf('دانگرید انجام شد — صفحه رفرش می‌شود');
    setTimeout(function(){ location.reload(); }, 500);
    return;
  }
  if(t.kind === 'snapshot' && t.snap){
    var wantIds = t.snap.updateIds || (t.snap.updates||[]).map(function(u){ return u.id; });
    var meta3 = getAppliedUpdatesMeta();
    var ordered = [];
    wantIds.forEach(function(id){
      for(var x=0;x<meta3.length;x++){ if(meta3[x].id===id){ ordered.push(meta3[x]); break; } }
    });
    var drop = meta3.filter(function(m){ return wantIds.indexOf(m.id) < 0; });
    await Promise.all(drop.map(function(m){ return deleteStoredUpdatePackage(m.id); }));
    saveAppliedUpdatesMeta(ordered);
    if(t.snap.version) setRuntimeAppVersion(t.snap.version, t.snap.versionFa);
    if(typeof ntf==='function') ntf('دانگرید به اسنپ‌شات انجام شد');
    setTimeout(function(){ location.reload(); }, 500);
  }
}
function refreshDowngradeSelect(){
  var sel = document.getElementById('upd-downgrade-select');
  if(!sel) return;
  var opts = listDowngradeTargets();
  sel.innerHTML = opts.map(function(o){
    return '<option value="'+String(o.key).replace(/"/g,'&quot;')+'">'+String(o.label).replace(/</g,'&lt;')+'</option>';
  }).join('');
}




